edits.oldText:
return Selector<PlaybackController, String?>(
  selector: (_, player) => player.songInfo?.track.path,
  builder: (context, playingPath, _) {
    // B-015: show the jump glyph when the playing track lives outside
    // the browsed folder; B-031 debounces the hide.
    final divergent =
        playingPath != null &&
        playingPath.isNotEmpty &&
        p.dirname(playingPath) != (path ?? '');
    final showJumpGlyph = resolveJumpGlyphVisible(divergent);
    // 12-px vertical padding preserves the crumb baseline; the 44×44
    // glyph hit target sits outside it (Material min, B-013).
    return Row(
      crossAxisAlignment: CrossAxisAlignment.center,
      children: [
        Expanded(
          child: Padding(
            padding: const EdgeInsets.fromLTRB(20, 12, 0, 12),
            child: MidEllipsis(
              text: path == null || path.isEmpty ? '~' : path,
              style: mono(palette.fgSecondary, typography.crumbSize),
            ),
          ),
        ),
        if (showJumpGlyph && playingPath != null)
          buildJumpGlyph(playingPath)
        else
          const SizedBox(width: 20),
      ],
    );
  },
);

edits.newText:
return Selector<PlaybackController,
    ({
      String? playingPath,
      ({int targetMs, int durationMs, double fraction})? seek,
    })>(
  selector: (_, player) => (
    playingPath: player.songInfo?.track.path,
    seek: seekFeedback.value,
  ),
  builder: (context, data, _) {
    final playingPath = data.playingPath;
    final preview = data.seek;

    // Linux: while scrubbing via horizontal drag, show the seek
    // preview in the bottom-folder (crumb) line.
    if (preview != null) {
      final durationMs = preview.durationMs;
      final targetMs = preview.targetMs;
      final progressPct = durationMs <= 0
          ? '--%'
          : '${(preview.fraction * 100).round()}%';
      final label = durationMs <= 0
          ? '--:-- / --:-- $progressPct'
          : '${formatClock(targetMs)} / ${formatClock(durationMs)} $progressPct';

      return Row(
        crossAxisAlignment: CrossAxisAlignment.center,
        children: [
          Expanded(
            child: Padding(
              padding: const EdgeInsets.fromLTRB(20, 12, 0, 12),
              child: MidEllipsis(
                text: label,
                style:
                    mono(palette.fgSecondary, typography.crumbSize),
              ),
            ),
          ),
          const SizedBox(width: 20),
        ],
      );
    }

    // B-015: show the jump glyph when the playing track lives outside
    // the browsed folder; B-031 debounces the hide.
    final divergent =
        playingPath != null &&
        playingPath.isNotEmpty &&
        p.dirname(playingPath) != (path ?? '');
    final showJumpGlyph = resolveJumpGlyphVisible(divergent);
    // 12-px vertical padding preserves the crumb baseline; the 44×44
    // glyph hit target sits outside it (Material min, B-013).
    return Row(
      crossAxisAlignment: CrossAxisAlignment.center,
      children: [
        Expanded(
          child: Padding(
            padding: const EdgeInsets.fromLTRB(20, 12, 0, 12),
            child: MidEllipsis(
              text: path == null || path.isEmpty ? '~' : path,
              style: mono(palette.fgSecondary, typography.crumbSize),
            ),
          ),
        ),
        if (showJumpGlyph && playingPath != null)
          buildJumpGlyph(playingPath)
        else
          const SizedBox(width: 20),
      ],
    );
  },
);
